def prepare_legacy_invitations(apps, schema_editor):
    Invitation = apps.get_model('api', 'UserInvitation')
    invitations = Invitation.objects.using(schema_editor.connection.alias)
    now = django.utils.timezone.now()
    active = set()
    for invite in invitations.order_by('-created_at', 'id').iterator():
        invite.email = invite.email.strip().lower()
        if invite.role == 'ADMIN':
            invite.role = 'DIRECTOR'
            invite.all_schools_access = True
        if invite.status == 'PENDING':
            key = (invite.organization_id, invite.email)
            if invite.expires_at <= now:
                invite.status = 'EXPIRED'
            elif not invite.all_schools_access or key in active:
                invite.status = 'REVOKED'
                invite.revoked_at = now
            else:
                active.add(key)
        invite.save(using=schema_editor.connection.alias, update_fields=[
            'email', 'role', 'all_schools_access', 'status', 'revoked_at',
        ])


